  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ApkAnalysisResult | null>(null);

  const handleAnalyze = async () => {
    if (!manifestText.trim()) return;
    setLoading(true);
    setResult(null);

    try {
      const data = await analyzeApkManifest(manifestText);
      setResult(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">
      <div className="space-y-4 flex flex-col h-full">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">APK Forensics</h2>
          <p className="text-slate-400 text-sm">
            Paste AndroidManifest.xml content or a list of permissions to analyze structural risks.
          </p>
        </div>

        <div className="flex-1 relative">
          <textarea
            className="w-full h-96 lg:h-full bg-slate-900/50 border border-slate-700 rounded-xl p-4 font-mono text-xs text-slate-300 focus:outline-none focus:border-cyan-500 resize-none custom-scrollbar"
            placeholder={`<manifest xmlns:android="http://schemas.android.com/apk/res/android" package="com.example.malicious">
    <uses-permission android:name="android.permission.SEND_SMS" />
    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />
    ...`}
            value={manifestText}
            onChange={(e) => setManifestText(e.target.value)}
          />
          <div className="absolute bottom-4 right-4">
            <button
              onClick={handleAnalyze}
              disabled={loading || !manifestText}
              className="bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-2 rounded-lg font-medium shadow-lg shadow-cyan-900/20 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
              {loading ? 'Analyzing...' : <><Terminal size={16} /> Analyze Manifest</>}
            </button>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        {result ? (
          <div className="animate-fade-in space-y-6">
            {/* Header Card */}
            <div className={`glass-panel p-6 rounded-xl border-l-4 ${result.riskLevel === 'CRITICAL' ? 'border-red-500' : result.riskLevel === 'HIGH' ? 'border-amber-500' : 'border-emerald-500'}`}>
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Package Analysis</h3>
                  <div className="text-2xl font-mono text-white mt-1">{result.packageName}</div>
                </div>
                <div className={`px-4 py-2 rounded-lg font-bold text-sm ${result.riskLevel === 'CRITICAL' ? 'bg-red-500/20 text-red-400' : 'bg-emerald-500/20 text-emerald-400'}`}>
                  {result.riskLevel} RISK
                </div>
              </div>
              <p className="mt-4 text-slate-300 text-sm leading-relaxed">
                {result.summary}
              </p>
            </div>

            {/* Permissions */}
            <div className="glass-panel p-6 rounded-xl">
              <h4 className="text-white font-semibold flex items-center gap-2 mb-4">
                <ShieldAlert className="text-amber-400" size={18} />
                Dangerous Permissions
              </h4>
              <ul className="space-y-2">
                {result.permissionsIssues.map((perm, i) => (
                  <li key={i} className="flex items-start gap-2 text-sm text-slate-300 bg-slate-800/50 p-2 rounded border border-slate-700/50">
                    <AlertTriangle size={14} className="text-amber-500 mt-0.5 shrink-0" />
                    <span className="font-mono">{perm}</span>
                  </li>
                ))}
                {result.permissionsIssues.length === 0 && (
                  <li className="text-slate-500 italic text-sm">No dangerous permissions found.</li>
                )}
              </ul>
            </div>

            {/* Hidden Capabilities */}
            <div className="glass-panel p-6 rounded-xl">
              <h4 className="text-white font-semibold flex items-center gap-2 mb-4">
